FramesToFade={}function BaseFrameFade(t,e)if(t)then
t.FadeTimer=0
if(t.time)then
t.TimeToFade=t.time
else
t.TimeToFade=3
end
t.FadeMode=e
table.insert(FramesToFade,t)end
end
function BaseFrameFadeIn(t,e)BaseFrameFade(t,"IN")t:Show()end
function BaseFrameFadeOut(t,e)BaseFrameFade(t,"OUT")end
function BaseFading(t)for e,t in pairs(FramesToFade)do
t.FadeTimer=t.FadeTimer+.1
if(t.FadeTimer<t.TimeToFade)then
if(t.FadeMode=="IN")then
t:SetAlpha(t.FadeTimer/t.TimeToFade)elseif(t.FadeMode=="OUT")then
t:SetAlpha((t.TimeToFade-t.FadeTimer)/t.TimeToFade)end
else
if(t.FadeMode=="IN")then
t:SetAlpha(1);elseif(t.FadeMode=="OUT")then
t:SetAlpha(0);t:Hide()end
table.remove(FramesToFade,e)end
end
end
